questions.solution:
import numpy as np


def softmax(logits):
    """Return the softmax of every row of logits, shape (N, K)."""
    exp_values = np.exp(logits - np.max(logits, axis=1, keepdims=True))
    return exp_values / np.sum(exp_values, axis=1, keepdims=True)
